 @Test public void wavExportPreservesSamplesAndWritesChosenDocument()throws Exception{
  System.setProperty("robolectric.enableShadowTtsSynthesisToFileWriteToFileSuppression","true");System.setProperty("robolectric.enableShadowTtsSynthesisToFileCallbackSuppression","true");
  SpeechAudioExport e=a.chrome.speech.export;e.begin(new SpeechProfile(GOOGLE,network.getName(),"pt",true,1f),0,"Esta narração pode ser ouvida sem Internet depois de ser guardada.");
  e.worker.submit(()->{}).get(20,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();assertNotNull(e.tts);shadowOf(e.tts).getOnInitListener().onInit(TextToSpeech.SUCCESS);shadowOf(Looper.getMainLooper()).idle();assertFalse(e.currentId.isEmpty());writeWav(e.chunk,new byte[]{1,2,3,4});shadowOf(e.tts).getUtteranceProgressListener().onDone(e.currentId);shadowOf(Looper.getMainLooper()).idle();for(int i=0;i<3;i++){e.worker.submit(()->{}).get(20,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();}
  assertNotNull(e.readyDialog);assertEquals(4,WaveJoiner.inspect(e.prepared).length);e.readyDialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();assertTrue(e.awaitingDestination);a.onActivityResult(SpeechAudioExport.REQUEST,Activity.RESULT_OK,new Intent().setData(Uri.parse("content://seeky.voice.test/saved.wav")));e.worker.submit(()->{}).get(20,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();assertTrue(savedFile.isFile());assertEquals(4,WaveJoiner.inspect(savedFile).length);byte[] saved=Files.readAllBytes(savedFile.toPath());assertArrayEquals(new byte[]{1,2,3,4},Arrays.copyOfRange(saved,44,48));assertFalse(e.busy);
 }
 @Test public void cancellingAnExportCleansItsPartialFiles()throws Exception{
  SpeechAudioExport e=a.chrome.speech.export;e.begin(new SpeechProfile(GOOGLE,local.getName(),"pt",false,1f),0,"Uma pequena narração.");e.worker.submit(()->{}).get(20,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();File prepared=e.prepared;assertNotNull(prepared);e.cancel();e.worker.submit(()->{}).get(20,TimeUnit.SECONDS);assertFalse(prepared.exists());assertFalse(new File(prepared+".part").exists());assertFalse(e.busy);
 }
 @Test public void multipleGeneratedChunksKeepTheirExactOrderAndIgnoreDuplicateCallbacks()throws Exception{
  System.setProperty("robolectric.enableShadowTtsSynthesisToFileWriteToFileSuppression","true");System.setProperty("robolectric.enableShadowTtsSynthesisToFileCallbackSuppression","true");
  StringBuilder input=new StringBuilder();for(int i=0;i<320;i++)input.append("Uma frase completa para leitura. ");
  SpeechAudioExport e=a.chrome.speech.export;e.begin(new SpeechProfile(GOOGLE,network.getName(),"pt",true,1f),0,input.toString());e.worker.submit(()->{}).get(20,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();shadowOf(e.tts).getOnInitListener().onInit(TextToSpeech.SUCCESS);shadowOf(Looper.getMainLooper()).idle();ByteArrayOutputStream expected=new ByteArrayOutputStream();int parts=0;
  while(e.readyDialog==null&&parts<20){if(!e.currentId.isEmpty()){String id=e.currentId;byte[] bytes={(byte)++parts,0};expected.write(bytes);writeWav(e.chunk,bytes);UtteranceProgressListener listener=shadowOf(e.tts).getUtteranceProgressListener();listener.onDone(id);listener.onDone(id);}for(int i=0;i<3;i++){e.worker.submit(()->{}).get(20,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();}}
  assertTrue(parts>1);assertNotNull(e.readyDialog);byte[] full=Files.readAllBytes(e.prepared.toPath());assertArrayEquals(expected.toByteArray(),Arrays.copyOfRange(full,44,44+expected.size()));e.cancel();e.worker.submit(()->{}).get(20,TimeUnit.SECONDS);
 }
 @Test public void aPreparedNarrationCanBeRestoredForTheDestinationPicker()throws Exception{
  SpeechAudioExport e=a.chrome.speech.export;File file=new File(e.directory(),"narration-"+UUID.randomUUID()+".wav");writeWav(file,new byte[]{1,2,3,4});Bundle state=new Bundle();state.putString("speech_export_file",file.getPath());state.putString("speech_export_title","Restored.wav");e.restore(state);assertTrue(e.awaitingDestination);assertEquals(file.getCanonicalFile(),e.prepared);e.result(SpeechAudioExport.REQUEST,Activity.RESULT_OK,new Intent().setData(Uri.parse("content://seeky.voice.test/saved.wav")));e.worker.submit(()->{}).get(20,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();assertEquals(4,WaveJoiner.inspect(savedFile).length);
  SpeechAudioExport other=new SpeechAudioExport(a);File outside=new File(a.getCacheDir(),"narration-"+UUID.randomUUID()+".wav");writeWav(outside,new byte[]{1,2});state.putString("speech_export_file",outside.getPath());other.restore(state);assertNull(other.prepared);other.close();assertTrue(outside.exists());
 }
