 @Test public void ambientPlaybackSurvivesClosingThePanelAndTheReader()throws Exception{
  File dir=new File(a.getFilesDir(),"backgrounds");dir.mkdirs();File track=new File(dir,"playback.audio");writeWav(track,new byte[]{1,0,2,0});a.getSharedPreferences("reading_background",0).edit().putString("path",track.getPath()).putString("name","Ambiente").putInt("volume",17).apply();ShadowMediaPlayer.addMediaInfo(org.robolectric.shadows.util.DataSource.toDataSource(track.getPath()),new ShadowMediaPlayer.MediaInfo(60000,0));
  a.chrome.speech.background.show();android.app.Dialog panel=ShadowDialog.getLatestDialog();android.view.View button=findText(panel.getWindow().getDecorView(),"Tocar durante a leitura");assertNotNull(button);button.performClick();Intent started=null;for(Intent next;(next=shadowOf(a).getNextStartedService())!=null;)if(next.getComponent()!=null&&next.getComponent().getClassName().equals(BackgroundAudioService.class.getName()))started=next;assertNotNull(started);
  ServiceController<BackgroundAudioService> service=Robolectric.buildService(BackgroundAudioService.class).create();BackgroundAudioService bg=service.get();try{bg.onStartCommand(started,0,1);shadowOf(Looper.getMainLooper()).idle();assertTrue(bg.background.player.isPlaying());assertTrue(bg.foreground);android.media.MediaPlayer player=bg.background.player;panel.dismiss();assertTrue(player.isPlaying());controller.pause().stop().destroy();controller=null;assertTrue(player.isPlaying());assertEquals(.17f,shadowOf(player).getLeftVolume(),.001f);BackgroundAudioService.follow(bg,true);BackgroundAudioService.follow(bg,false);assertSame(player,bg.background.player);assertTrue(player.isPlaying());bg.prefs.edit().putInt("volume",31).apply();shadowOf(Looper.getMainLooper()).idle();assertEquals(.31f,shadowOf(player).getLeftVolume(),.001f);bg.onStartCommand(new Intent().setAction(BackgroundAudioService.STOP),0,2);assertFalse(bg.desired);assertFalse(player.isPlaying());}finally{service.destroy();}
 }
 @Test public void voiceAndBackgroundShareFocusAndBothReceiveExternalLoss(){ReadingAudioFocus gate=ReadingAudioFocus.get(a);Object voice=new Object(),music=new Object();int[] losses={0};assertTrue(gate.acquire(voice,()->losses[0]++));assertTrue(gate.acquire(music,()->losses[0]++));assertEquals(2,gate.owners.size());gate.release(voice);assertTrue(gate.granted);assertTrue(gate.owners.containsKey(music));assertTrue(gate.acquire(voice,()->losses[0]++));org.robolectric.util.ReflectionHelpers.<android.media.AudioManager.OnAudioFocusChangeListener>callInstanceMethod(gate.request,"getOnAudioFocusChangeListener").onAudioFocusChange(android.media.AudioManager.AUDIOFOCUS_LOSS);assertEquals(2,losses[0]);assertTrue(gate.owners.isEmpty());assertFalse(gate.granted);}
 @Test public void transportSelectsTenTwentyOrThirtySecondsAndIssuesMatchingCommands()throws Exception{SpeechEvents.publish(new SpeechEvents.State(a.uri.toString(),"voice-token","A ler em voz alta",1,3,0,true,false));try{SpeechTransport controls=(SpeechTransport)a.chrome.speechBar;assertEquals(android.view.View.VISIBLE,controls.getVisibility());controls.step.performClick();UiDialog dialog=(UiDialog)ShadowDialog.getLatestDialog();dialog.spec.choice.onClick(dialog,2);shadowOf(Looper.getMainLooper()).idle();assertEquals(30,a.getSharedPreferences("seeky",0).getInt("speech_seek_seconds",0));assertEquals("−30 s",controls.back.getText().toString());assertEquals("+30 s",controls.forward.getText().toString());controls.back.performClick();controls.forward.performClick();controls.previous.performClick();java.util.Set<String> actions=new java.util.HashSet<>();for(Intent i;(i=shadowOf(a).getNextStartedService())!=null;)actions.add(i.getAction());assertTrue(actions.contains(ReadAloudService.REWIND));assertTrue(actions.contains(ReadAloudService.FORWARD));assertTrue(actions.contains(ReadAloudService.PREVIOUS));a.root.measure(android.view.View.MeasureSpec.makeMeasureSpec(320,android.view.View.MeasureSpec.EXACTLY),android.view.View.MeasureSpec.makeMeasureSpec(640,android.view.View.MeasureSpec.EXACTLY));a.root.layout(0,0,320,640);assertTrue(controls.back.getWidth()>=40);android.graphics.Bitmap screen=android.graphics.Bitmap.createBitmap(320,640,android.graphics.Bitmap.Config.ARGB_8888);a.root.draw(new android.graphics.Canvas(screen));try(FileOutputStream out=new FileOutputStream(System.getProperty("seeky.screenshot")+"-speech-controls.png")){screen.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}screen.recycle();}finally{SpeechEvents.publish(new SpeechEvents.State("","","",0,0,0,false,true));}}
 static android.view.View findText(android.view.View view,String text){if(view instanceof android.widget.TextView&&((android.widget.TextView)view).getText().toString().equals(text))return view;if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++){android.view.View found=findText(group.getChildAt(i),text);if(found!=null)return found;}}return null;}
