 static void writeWav(File file,byte[] data)throws IOException{try(RandomAccessFile out=new RandomAccessFile(file,"rw")){out.writeInt(0x52494646);WaveJoiner.write32(out,36+data.length);out.writeInt(0x57415645);out.writeInt(0x666d7420);WaveJoiner.write32(out,16);WaveJoiner.write16(out,1);WaveJoiner.write16(out,1);WaveJoiner.write32(out,24000);WaveJoiner.write32(out,48000);WaveJoiner.write16(out,2);WaveJoiner.write16(out,16);out.writeInt(0x64617461);WaveJoiner.write32(out,data.length);out.write(data);}}
