 @Test public void naturalEngineSwitchesToOfflineWithoutChangingGooglePreference(){addNaturalEngine();ReaderSpeech s=a.chrome.speech;s.show();ready(s);s.modes.setSelection(1);shadowOf(Looper.getMainLooper()).idle();s.engines.setSelection(s.engineIds.indexOf(NaturalVoicesActivity.ENGINE));shadowOf(Looper.getMainLooper()).idle();assertEquals(NaturalVoicesActivity.ENGINE,s.engine());assertFalse(s.online());assertEquals(GOOGLE,s.prefs.getString("speech_engine",""));}
 @Test public void naturalVoiceNamesAreDisplayedAndSavedWithExactEngine(){addNaturalEngine();Voice tugao=new Voice("Tugão",new Locale("pt","PT"),Voice.QUALITY_HIGH,Voice.LATENCY_NORMAL,false,Collections.emptySet());ShadowTextToSpeech.addVoice(tugao);ReaderSpeech s=a.chrome.speech;s.show();ready(s);s.engines.setSelection(s.engineIds.indexOf(NaturalVoicesActivity.ENGINE));shadowOf(Looper.getMainLooper()).idle();ready(s);int index=-1;for(int n=0;n<s.voices.size();n++)if(s.voices.get(n).getName().equals("Tugão"))index=n;assertTrue(index>=0);assertTrue(s.voicePicker.getAdapter().getItem(index).toString().contains("Tugão"));s.voicePicker.setSelection(index);shadowOf(Looper.getMainLooper()).idle();s.apply.performClick();assertEquals(NaturalVoicesActivity.ENGINE,s.prefs.getString("speech_engine",""));assertEquals("Tugão",s.prefs.getString("speech_voice",""));assertFalse(s.prefs.getBoolean("speech_online",true));}
 @Test public void spanishAndFrenchVoicesUseTheirOwnSamplesAndPreserveLanguage(){Voice spanish=new Voice("DaveFX",new Locale("es","ES"),Voice.QUALITY_HIGH,Voice.LATENCY_NORMAL,false,Collections.emptySet());Voice french=new Voice("Siwis",Locale.FRANCE,Voice.QUALITY_HIGH,Voice.LATENCY_NORMAL,false,Collections.emptySet());ShadowTextToSpeech.addVoice(spanish);ShadowTextToSpeech.addVoice(french);ReaderSpeech s=a.chrome.speech;s.show();ready(s);s.languages.setSelection(2);shadowOf(Looper.getMainLooper()).idle();assertEquals("es",s.language());s.sample();assertTrue(shadowOf(s.discovery).getLastSpokenText().startsWith("Hola"));s.stopSample();s.languages.setSelection(3);shadowOf(Looper.getMainLooper()).idle();assertEquals("fr",s.language());s.sample();assertTrue(shadowOf(s.discovery).getLastSpokenText().startsWith("Bonjour"));}
 @Test public void companionDownloadsOpenInsideTheSeekySetupScreen(){addNaturalEngine();ReaderSpeech s=a.chrome.speech;s.show();ready(s);s.engines.setSelection(s.engineIds.indexOf(NaturalVoicesActivity.ENGINE));shadowOf(Looper.getMainLooper()).idle();s.installVoices();assertEquals(NaturalVoicesActivity.class.getName(),shadowOf(a).getNextStartedActivity().getComponent().getClassName());assertTrue(s.needsReload);}


 @Config(shadows={NeverInitializes.class})
 @Test public void aMissingEngineCallbackStopsLoadingAndDiscardsItsLateResult(){ReaderSpeech s=a.chrome.speech;s.show();TextToSpeech old=s.discovery;shadowOf(Looper.getMainLooper()).idleFor(13,TimeUnit.SECONDS);assertFalse(s.ready);assertNull(s.discovery);assertTrue("timeout status: "+s.info.getText(),s.info.getText().toString().contains("não respondeu"));assertFalse(s.voicePicker.getSelectedItem().toString().contains("A carregar"));assertEquals(android.view.View.VISIBLE,s.retry.getVisibility());NeverInitializes.captured.onInit(TextToSpeech.SUCCESS);shadowOf(Looper.getMainLooper()).idle();assertFalse(s.ready);assertTrue(s.available.isEmpty());}
 @Test public void naturalSamplesCanBeOpenedBeforeInstallingVoiceData(){naturalMissing=true;addNaturalEngine();Voice missing=new Voice("Tugão",new Locale("pt","PT"),400,200,false,Collections.singleton(TextToSpeech.Engine.KEY_FEATURE_NOT_INSTALLED));ShadowTextToSpeech.addVoice(missing);ReaderSpeech s=a.chrome.speech;s.show();ready(s);s.engines.setSelection(s.engineIds.indexOf(NaturalVoicesActivity.ENGINE));shadowOf(Looper.getMainLooper()).idle();ready(s);int at=-1;for(int i=0;i<s.voices.size();i++)if(s.voices.get(i).getName().equals("Tugão"))at=i;assertTrue(at>=0);s.voicePicker.setSelection(at);shadowOf(Looper.getMainLooper()).idle();assertTrue(s.preview.isEnabled());assertFalse(s.start.isEnabled());s.sample();Intent opened=shadowOf(a).getNextStartedActivity();assertEquals(NaturalVoicesActivity.ENGINE,opened.getComponent().getPackageName());assertEquals("Tugão",opened.getStringExtra("preview_voice"));}
 @Test public void losingTheNaturalEngineClearsItsCatalogueAndAllowsRetry()throws Exception{addNaturalEngine();ReaderSpeech s=a.chrome.speech;s.show();ready(s);s.engines.setSelection(s.engineIds.indexOf(NaturalVoicesActivity.ENGINE));shadowOf(Looper.getMainLooper()).idle();ready(s);assertTrue(s.ready);java.lang.reflect.Field field=mz.bam.seeky.voicebridge.NaturalSpeech.class.getDeclaredField("connection");field.setAccessible(true);android.content.ServiceConnection connection=(android.content.ServiceConnection)field.get(s.discovery);connection.onServiceDisconnected(new android.content.ComponentName(NaturalVoicesActivity.ENGINE,mz.bam.seeky.voicebridge.NaturalSpeech.SERVICE));shadowOf(Looper.getMainLooper()).idle();assertFalse(s.ready);assertTrue(s.available.isEmpty());assertTrue(s.info.getText().toString().contains("interrompido"));assertFalse(s.info.getText().toString().contains("actualização"));assertEquals(android.view.View.VISIBLE,s.retry.getVisibility());assertFalse(s.start.isEnabled());}
 @Implements(TextToSpeech.class) public static class NeverInitializes extends ShadowTextToSpeech {static TextToSpeech.OnInitListener captured;@Implementation protected void __constructor__(Context c,TextToSpeech.OnInitListener listener,String engine,String packageName,boolean fallback){captured=listener;}@Implementation protected int initTts(){return TextToSpeech.SUCCESS;}}
